                + "function categoryScenarioIndex(link,id){var root=document.querySelector('#test-view .test-item[test-id=\"'+id+'\"]');if(!root)return 0;var expected=text(link,'').replace(/\\s+/g,' ').trim(),cards=directScenarioCards(root);for(var i=0;i<cards.length;i++){if(text(cards[i],'.card-title .node').replace(/\\s+/g,' ').trim()===expected)return i;}return 0;}"
                + "function openCategoryTest(id,index){if(index===undefined){atfOpenTest(id);}else{atfOpenTest(id,index);}}"
                + "function normalizeCategoryLinks(){q('#category-view .test-content-detail a.linked[test-id]').forEach(function(link){var id=link.getAttribute('test-id');if(!id)return;var index=categoryScenarioIndex(link,id);link.setAttribute('data-atf-test-id',id);link.setAttribute('data-atf-scenario-index',String(index));link.setAttribute('href','#test-id='+id+'&scenario-index='+index);link.setAttribute('title','Open this test in Tests');link.onclick=function(e){e.preventDefault();e.stopPropagation();openCategoryTest(id,index);return false;};});}"
                + "function renderCategoryDetail(item){var detail=document.querySelector('#category-view .test-content-detail .detail-body'),source=item&&item.querySelector(':scope>.test-contents');if(!detail||!source)return;detail.innerHTML='';var projection=source.cloneNode(true);projection.classList.remove('d-none');projection.classList.add('atf-category-detail');detail.appendChild(projection);var title=projection.querySelector(':scope>.info>h4');if(title)title.setAttribute('data-atf-category-title','true');normalizeCategoryLinks();}"
                + "function selectCategory(item){if(!item)return;categoryItems().forEach(function(candidate){candidate.classList.toggle('active',candidate===item);});atfCategoryState.selectedName=text(item,'.test-detail .name');renderCategoryDetail(item);}"
                + "function bindCategorySelection(){categoryItems().forEach(function(item){if(item.getAttribute('data-atf-category-bound'))return;item.setAttribute('data-atf-category-bound','true');item.addEventListener('click',function(e){e.preventDefault();e.stopImmediatePropagation();e.stopPropagation();selectCategory(item);},true);});}"
                + "function ensureCategoryDetail(){bindCategorySelection();var selected=categoryItems().find(function(item){return item.classList.contains('active');})||categoryItems()[0];if(selected)selectCategory(selected);}"
                + "function normalizeTagFilter(){var excluded={'failure':true,'reporting':true,'skip':true,'soft-assert':true,'teardown':true,'warning':true};q('#tag-toggle .dropdown-item').forEach(function(item){var value=String(item.textContent||'').trim().toLowerCase();if(excluded[value])item.remove();});}"
                + "function isScenarioCard(card){var accordion=card&&card.parentElement,host=accordion&&accordion.parentElement,contents=host&&host.parentElement;return !!(accordion&&accordion.classList.contains('accordion')&&host&&host.classList.contains('mt-4')&&contents&&contents.classList.contains('test-contents'));}"
                + "function normalizeScenarioAnnotations(){q('.test-contents > .mt-4 > .accordion > .card[data-atf-scenario-id]').forEach(function(card){var header=card.querySelector(':scope > .card-header'),title=header&&header.querySelector(':scope > .card-title');if(!header||!title)return;var captured=readTagValues(card);if(captured.length)card.setAttribute('data-atf-scenario-tags',captured.join(' '));var annotation=title.querySelector(':scope > .atf-scenario-annotations'),source=card.querySelector(':scope > .accordion > .card .card-title > .node-attr');if(!annotation&&source){annotation=document.createElement('div');annotation.className='atf-scenario-annotations';annotation.setAttribute('role','list');annotation.setAttribute('aria-label','Scenario annotations');source.querySelectorAll('.badge').forEach(function(badge){var tag=document.createElement('span');tag.className='atf-tag-annotation atf-tag-annotation-selection';tag.setAttribute('role','listitem');tag.setAttribute('data-atf-tag-kind','selection');tag.textContent=String(badge.textContent||'').replace(/^\\s*[^a-zA-Z0-9_-]\\s*/,'').trim();if(tag.textContent)annotation.appendChild(tag);});title.appendChild(annotation);}if(source&&annotation)source.remove();title.querySelectorAll(':scope > .node-attr').forEach(function(attrs){attrs.remove();});card.querySelectorAll(':scope > .accordion .node-attr').forEach(function(attrs){attrs.remove();});});}";
